 safety='Use only a licensed partner and its test mode. Never store card numbers, passwords or keys. Holding customer money needs a licence: this course does not.',
 mods=[
 ('How a wallet payment moves', 'Follow the money step by step.', ['Customer authorises; the wallet provider checks funds and identity.', 'Merchant is told yes or no; money settles later.', 'Fees are taken before settlement.', 'Records on both sides must match.'], 'A 100.00 sale with a 2% fee settles as 98.00 two days later; ledger shows sale, fee and settlement.', 'Draw the flow with arrows and time.', 'Flow shows each party and time.'),
 ('Choosing a partner', 'Pick on safety and fit, not on price alone.', ['Licensed and regulated; clear terms.', 'Fees: percent, fixed, refund and dispute fees.', 'Settlement time; support; local methods.', 'Data handling and security.'], 'Partner A 2.0% + 0.20; partner B 1.6% + 0.50. On a 10.00 sale: A = 0.40, B = 0.66, so A is cheaper for small sales.', 'Compare three partners on a table.', 'Fees calculated on three sale sizes.'),
 ('Test mode set-up', 'Always rehearse without real money.', ['Create a test account; use test credentials supplied.', 'Link a simple checkout.', 'Use test wallets to simulate success and failure.', 'Keep keys private and out of documents.'], 'Test wallet 1 always succeeds; test wallet 2 declines for no funds; both paths must show a clear message.', 'Run 10 test payments.', 'All ten recorded.'),
 ('Receipts and records', 'Customers and tax offices need clear proof.', ['Receipt: date, seller, items, taxes, total, reference.', 'Number receipts in order.', 'Send by email or message with consent.', 'Keep records for the legal period.'], 'Receipt 000127: 3 items, tax 5.00, total 55.00, reference matches the partner\'s record.', 'Design a receipt and send one in test mode.', 'Receipt has all fields.'),
 ('Failures and refunds', 'Things go wrong: plan for them.', ['Common failures: low funds, timeout, wrong details.', 'Say what happened and what to do next.', 'Refund rules: when, how long, who pays the fee.', 'Avoid double charges.'], 'A timeout charges twice; the guide explains the second charge is released in 3 days or refunded now on request.', 'Test 3 failures and 2 refunds.', 'Messages are clear and kind.'),
 ('Fraud and security', 'Protect the customer and the shop.', ['Signs: unusual size, rushed buyers, mismatched details.', 'Use partner tools for checks.', 'Limit who can refund.', 'Never ask for a password or code.'], 'Order of 40 phones in one go from a new account: hold and verify.', 'Write a fraud checklist.', 'Checklist has actions, not just signs.'),
 ('Reconcile and measure', 'Match every payment to a record.', ['Daily match: partner report versus own sales log.', 'Investigate any gap.', 'Measures: success rate, time to pay, refund rate.', 'Chargebacks: reasons and prevention.'], '100 attempts: 93 succeeded = 93% success; 4 refunded = 4%; average time to pay 38 seconds.', 'Reconcile 20 transactions and compute measures.', 'Reconciliation has no unexplained gap.'),
 ('Guide and review', 'Teach customers and improve.', ['One-page guide with pictures.', 'Test it with three real users.', 'Fix confusing steps.', 'Plan 90 days.'], 'Users misread "Authorise"; the screen is changed to "Pay 55.00 now".', 'Write, test and revise the guide.', 'Three users complete it alone.')],
 quiz=[('What is settlement?', 'The partner paying the merchant after a sale.'), ('Why test mode?', 'To rehearse without real money.'), ('What is in a receipt?', 'Date, seller, items, taxes, total and reference.'), ('Compute a fee: 2% + 0.20 on 10.00.', '0.20 + 0.20 = 0.40.'), ('Name two failure causes.', 'Low funds and timeout.'), ('Who must hold the licence for holding money?', 'The licensed partner, not this course.'), ('What do you never store?', 'Card numbers, passwords, keys.'), ('What is reconciliation?', 'Matching payments to records.'), ('A sign of fraud?', 'Unusually large or rushed order with mismatched details.'), ('How is success rate computed?', 'Successful payments divided by attempts.')],
