C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Trace one 20 unit payment through five steps on paper: customer taps pay, wallet app sends a token, partner checks it, the bank approves, and the shop receives a confirmation.', 'Learn the words authorise, capture and settle: authorise reserves the money, capture claims it, and settlement moves it to your account, often one to three working days later.'], ['Score three licensed partners from 1 to 5 on fee clarity, support response, test tools, payout speed and reporting, and favour the one with the highest total, not the lowest price.', 'Ask each partner in writing for their list of fees, their payout schedule and what they do when a payment is disputed, and keep the replies in a folder.'], ['Work only with test keys and fake card numbers supplied by the partner, and keep the secret key out of web pages, shared documents and screenshots.', 'Run at least ten test payments: five that succeed, three that are declined, and two that time out, and note exactly what the screen shows in each case.'], ['Send a receipt to every customer within one minute, showing date, items, total, tax if any, a payment reference and a contact for questions.', "Keep a monthly record file with one row per payment and store a copy outside the system; check that the number of rows equals the partner's report each week."], ['Write a plain message for each failure: card declined, timeout, duplicate charge and wrong amount, telling the customer what happened and the next step in under 25 words.', 'Set a refund routine: confirm the order, refund to the original method, send a message, and record the date; aim to complete it within two working days.'], ['Add simple limits: block more than five failed attempts per card in an hour, flag orders far above your usual size, and require two people to approve large refunds.', 'Keep software and passwords updated, turn on two-step sign-in for every account, and remove access the day a team member leaves.'], ["Each week, match the partner's payout report to your own records line by line; any difference above 1 unit or any missing payment goes on a short follow-up list.", 'Track three measures monthly: the percentage of payments that succeed, the average time to payout and the refund rate, and compare month to month.'], ['Write a one-page customer guide with three steps to pay, what to do if it fails and how to ask for a refund, in language a ten-year-old could follow.', 'Review the pilot after two weeks with test users, listing what confused them, and only plan real money after a licensed partner and an adviser have approved the setup.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
